import 'package:flutter/material.dart';
import 'package:priceshield/core/services/priceshield_api_client.dart';
import 'package:priceshield/features/complaints/presentation/screens/complaint_details_screen.dart';
class ComplaintsScreen extends StatefulWidget { const ComplaintsScreen({super.key}); @override State<ComplaintsScreen> createState() => _ComplaintsScreenState(); }
class _ComplaintsScreenState extends State<ComplaintsScreen> {
  late Future<List<Map<String, dynamic>>> _complaints = priceShieldApi.listComplaints(limit: 100);
  void _refresh() => setState(() => _complaints = priceShieldApi.listComplaints(limit: 100));
  @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('My Complaints')), body: FutureBuilder<List<Map<String, dynamic>>>(future: _complaints, builder: (context, snapshot) { if (snapshot.connectionState != ConnectionState.done) return const Center(child: CircularProgressIndicator()); if (snapshot.hasError) return Center(child: Padding(padding: const EdgeInsets.all(24), child: Text(snapshot.error is PriceShieldApiException ? (snapshot.error as PriceShieldApiException).message : 'Could not load complaints.'))); final entries = snapshot.data ?? []; if (entries.isEmpty) return RefreshIndicator(onRefresh: () async => _refresh(), child: ListView(children: const [SizedBox(height: 220), Center(child: Text('No complaints filed yet.'))])); return RefreshIndicator(onRefresh: () async => _refresh(), child: ListView.builder(itemCount: entries.length, itemBuilder: (context, index) { final item = entries[index]; return Card(margin: const EdgeInsets.symmetric(horizontal: 16, vertical: 7), child: ListTile(title: Text(item['productName']?.toString() ?? 'Product'), subtitle: Text('Status: ${item['status'] ?? 'PENDING'}'), trailing: Text('₹${item['overcharge'] ?? 0}'), onTap: () async { await Navigator.push(context, MaterialPageRoute(builder: (_) => ComplaintDetailsScreen(complaintId: item['id'].toString()))); _refresh(); })); })); }));
}
